214	// TestAssemblyEntryErrorPriority pins the error ordering on the new entry:
215	// invalid input is a 400 decided before any storage call — even while the
216	// store is down — and a legal request that hits a failing store is a 503.
217	func TestAssemblyEntryErrorPriority(t *testing.T) {
218		st := newAssemblyStore()
219		router := newAssemblyRouter(st, &assemblyProbe{})
220	
221		// Invalid registration and query bodies are rejected without touching the
222		// store, while it is still healthy.
223		assertErrorResponse(t, postArtifact(t, router, `{"repository":`),
224			http.StatusBadRequest, codeInvalidInput, msgInvalidReg)
225		assertErrorResponse(t, postArtifact(t, router, registrationWithField("size_bytes", "null")),
226			http.StatusBadRequest, codeInvalidInput, msgInvalidReg)
227		assertErrorResponse(t, getArtifacts(t, router, "tag="+sequenceTag),
228			http.StatusBadRequest, codeInvalidInput, msgInvalidQuery)
229		assertErrorResponse(t, getArtifacts(t, router, "repository="+sequenceRepo+"&tag=&digest="),
230			http.StatusBadRequest, codeInvalidInput, msgInvalidQuery)
231		if got := st.totalCalls(); got != 0 {
232			t.Fatalf("invalid input reached the store %d times, want 0", got)
233		}
234	
235		// With the store faulted, invalid input still wins its 400 over the 503.
236		st.fault = errors.New("assembly backend down")
237		assertErrorResponse(t, postArtifact(t, router, registrationWithField("signature_verified", "null")),
238			http.StatusBadRequest, codeInvalidInput, msgInvalidReg)
239		assertErrorResponse(t, getArtifacts(t, router, "repository="+sequenceRepo+"&digest=sha256:xyz"),
240			http.StatusBadRequest, codeInvalidInput, msgInvalidQuery)
241	
242		// Legal requests degrade to 503 storage_unavailable on the same faulted
243		// store, register and query alike.
244		assertErrorResponse(t, postArtifact(t, router,
245			registration(sequenceRepo, testDigestA, sequenceTag, true, regRetention, regSizeA)),
246			http.StatusServiceUnavailable, codeStorage, msgStorage)
247		assertErrorResponse(t, queryList(t, router, sequenceRepo),
248			http.StatusServiceUnavailable, codeStorage, msgStorage)
249		assertErrorResponse(t, queryByTag(t, router, sequenceRepo, sequenceTag),
250			http.StatusServiceUnavailable, codeStorage, msgStorage)
251		assertErrorResponse(t, queryByDigest(t, router, sequenceRepo, testDigestA),
252			http.StatusServiceUnavailable, codeStorage, msgStorage)
253	}
254	
255	// TestAssemblyHealthCheckIndependent proves the health check and the store
256	// answer for themselves alone: a failing probe degrades only /healthz, a
257	// failing store degrades only the artifact entries, and /healthz reflects the
258	// probe result on every single call.
259	func TestAssemblyHealthCheckIndependent(t *testing.T) {
260		st := newAssemblyStore()
261		probe := &assemblyProbe{}
262		router := newAssemblyRouter(st, probe)
263	
264		bodyA := registration(sequenceRepo, testDigestA, sequenceTag, true, regRetention, regSizeA)
265	
266		// Healthy probe: the published 200 body.
267		recorder := getHealth(t, router)
268		if recorder.Code != http.StatusOK || recorder.Body.String() != `{"database":"ok","status":"ok"}` {
269			t.Fatalf("healthy /healthz = %d %s", recorder.Code, recorder.Body)
270		}
271	
272		// Failing probe: /healthz is 503 with the published shape, but
273		// registration and queries are not gated on the probe and still succeed.
274		probe.err = errors.New("probe: dependency unreachable")
275		assertErrorResponse(t, getHealth(t, router),
276			http.StatusServiceUnavailable, codeStorage, msgStorage)
277		if got := postArtifact(t, router, bodyA); got.Code != http.StatusCreated {
278			t.Fatalf("register with failing probe status = %d (%s)", got.Code, got.Body)
279		}
280		if got := soleRecord(t, queryByTag(t, router, sequenceRepo, sequenceTag)); got["digest"] != testDigestA {
281			t.Fatalf("query with failing probe = %v, want the registered record", got)
282		}
283	
284		// The probe is consulted on every call: clearing the fault restores 200.
285		probe.err = nil
286		if recorder := getHealth(t, router); recorder.Code != http.StatusOK {
287			t.Fatalf("/healthz after probe recovery = %d, want %d", recorder.Code, http.StatusOK)
288		}
289		if probe.calls != 3 {
290			t.Fatalf("probe consulted %d times for 3 /healthz calls", probe.calls)
291		}
292	
293		// A failing store does not stand in for the health check: /healthz stays
294		// 200 on the healthy probe while legal artifact requests are 503.
295		st.fault = errors.New("assembly backend down")
296		if recorder := getHealth(t, router); recorder.Code != http.StatusOK {
297			t.Fatalf("/healthz with failing store = %d, want %d", recorder.Code, http.StatusOK)
298		}
299		assertErrorResponse(t, postArtifact(t, router,
300			registration(sequenceRepo, testDigestB, sequenceTag, true, regRetention, regSizeB)),
301			http.StatusServiceUnavailable, codeStorage, msgStorage)
302		assertErrorResponse(t, queryList(t, router, sequenceRepo),
303			http.StatusServiceUnavailable, codeStorage, msgStorage)
304	}
305	
306	// TestAssemblyEntryUnknownRoute keeps the published 404 shape on the new
307	// entry, independent of store and probe state.
308	func TestAssemblyEntryUnknownRoute(t *testing.T) {
309		router := newAssemblyRouter(newAssemblyStore(), &assemblyProbe{})
310	
311		recorder := httptest.NewRecorder()
312		router.ServeHTTP(recorder, httptest.NewRequest(http.MethodGet, "/missing", nil))
313		assertErrorResponse(t, recorder, http.StatusNotFound, "route_not_found", "no route matches this path")
314	}
315	
316	// TestSQLiteEntryStaysCompatibleWithExistingData writes records through the
317	// original NewRouter assembly, reopens the same database file behind the new
318	// NewRouterWithStore entry and confirms the committed data — push times, list
319	// order, unique identity and the current tag pointer — reads back unchanged,
320	// and that the new entry keeps registering into the same store.
321	func TestSQLiteEntryStaysCompatibleWithExistingData(t *testing.T) {
322		path := filepath.Join(t.TempDir(), "service.db")
323	
324		st, err := store.Open(path)
325		if err != nil {
326			t.Fatalf("open: %v", err)
327		}
328		legacy := NewRouter(st)
329		first := postArtifact(t, legacy, registration(sequenceRepo, testDigestA, sequenceTag, true, regRetention, regSizeA))
330		if first.Code != http.StatusCreated {
331			t.Fatalf("legacy register A status = %d (%s)", first.Code, first.Body)
332		}
333		pushedA := decodeBody(t, first)["pushed_at"].(string)
334		second := postArtifact(t, legacy, registration(sequenceRepo, testDigestB, sequenceTag, true, regRetention, regSizeB))
335		if second.Code != http.StatusCreated {
336			t.Fatalf("legacy register B status = %d (%s)", second.Code, second.Body)
337		}
338		pushedB := decodeBody(t, second)["pushed_at"].(string)
339		if err := st.Close(); err != nil {
340			t.Fatalf("close before reopen: %v", err)
341		}
342	
343		// Reopen the same file behind the new entry; the store's Ping is passed
344		// explicitly as the health check, like NewRouter does.
345		reopened, err := store.Open(path)
346		if err != nil {
347			t.Fatalf("reopen: %v", err)
348		}
349		t.Cleanup(func() { reopened.Close() })
350		router := NewRouterWithStore(reopened, reopened.Ping)
351	
352		// Existing data survives: order, push times and the tag pointer.
353		records := allRecords(t, queryList(t, router, sequenceRepo))
354		if digests := recordDigests(records); len(digests) != 2 ||
355			digests[0] != testDigestA || digests[1] != testDigestB {
356			t.Fatalf("list after reopen = %v, want A then B", digests)
357		}
358		if records[0].(map[string]any)["pushed_at"] != pushedA ||
359			records[1].(map[string]any)["pushed_at"] != pushedB {
360			t.Fatalf("pushed_at values did not survive reopen: %v", records)
361		}
362		tagged := soleRecord(t, queryByTag(t, router, sequenceRepo, sequenceTag))
363		if tagged["digest"] != testDigestB || tagged["pushed_at"] != pushedB {
364			t.Fatalf("tag pointer did not survive reopen: %v", tagged)
365		}
366	
367		// The unique identity still holds across the boundary: a verbatim retry of
368		// A through the new entry is a duplicate, not a new record.
369		retry := postArtifact(t, router, registration(sequenceRepo, testDigestA, sequenceTag, true, regRetention, regSizeA))
370		if retry.Code != http.StatusCreated {
371			t.Fatalf("retry A status = %d (%s)", retry.Code, retry.Body)
372		}
373		if got := decodeBody(t, retry)["pushed_at"]; got != pushedA {
374			t.Fatalf("retry pushed_at = %v, want original %v", got, pushedA)
375		}
376		if digests := recordDigests(allRecords(t, queryList(t, router, sequenceRepo))); len(digests) != 2 {
377			t.Fatalf("retry added a record across the boundary: %v", digests)
378		}
379	
380		// New registrations through the new entry land in the same store and are
381		// visible to a fresh legacy router on the same file.
382		third := postArtifact(t, router,
383			registration(sequenceRepo, testDigestC, sequenceTag, true, regRetention, regSizeB))
384		if third.Code != http.StatusCreated {
385			t.Fatalf("register C status = %d (%s)", third.Code, third.Body)
386		}
387		pushedC := decodeBody(t, third)["pushed_at"].(string)
388		if got := soleRecord(t, queryByTag(t, router, sequenceRepo, sequenceTag)); got["digest"] != testDigestC {
389			t.Fatalf("tag after C points at %v, want %s", got["digest"], testDigestC)
390		}
