package api

// These regression cases pin the boundary of one POST /v1/artifacts
// registration from request cancellation to response delivery, on both
// router construction entries (NewRouter and NewRouterWithStore) backed by
// the bundled SQLite store. They separate three things the public contract
// keeps distinct: the request context being cancelled before processing, the
// request body failing to read, and the client never receiving the success
// response. Every observable result is asserted through the public GET
// /v1/artifacts surface; no test relies on sleeps or network-cut timing.
//
// The committed-state conclusions are those of the bundled SQLite adapter.
// A caller-supplied service.Store provides the same guarantees solely
// through its own implementation.

import (
	"context"
	"errors"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"strings"
	"testing"

	"github.com/gin-gonic/gin"

	"github.com/Bob-xisuke/orb-registry-catalog/internal/store"
)

// deliveryEntries builds the two published router construction entries over
// one bundled SQLite store each, so every scenario runs identically through
// both assemblies.
func deliveryEntries(t *testing.T) map[string]*gin.Engine {
	t.Helper()
	entries := map[string]*gin.Engine{}
	for name, build := range map[string]func(*store.Store) *gin.Engine{
		"NewRouter":          NewRouter,
		"NewRouterWithStore": func(st *store.Store) *gin.Engine { return NewRouterWithStore(st, st.Ping) },
	} {
		st, err := store.Open(filepath.Join(t.TempDir(), "service.db"))
		if err != nil {
			t.Fatalf("open store for %s: %v", name, err)
		}
		t.Cleanup(func() { st.Close() })
		entries[name] = build(st)
	}
	return entries
}
