// failAfterReader yields the given bytes across reads and then fails every
// subsequent read with err. It models a transport that delivered a complete
// JSON object and then broke before the end of the body could be confirmed.
type failAfterReader struct {
	data []byte
	err  error
}

func (f *failAfterReader) Read(p []byte) (int, error) {
	if len(f.data) == 0 {
		return 0, f.err
	}
	n := copy(p, f.data)
	f.data = f.data[n:]
	return n, nil
}

// TestBodyReadFailureRejectsWithoutStoreWrite ...
func TestBodyReadFailureRejectsWithoutStoreWrite(t *testing.T) {
